#!/usr/bin/env python3
"""Read-only audit of ESP32 partition table generated by PlatformIO.

Does not connect to a device, run esptool, or modify any flash content.
Usage: python scripts/audit-partitions.py [--env infotab_tab5_16mb_audit]
"""
from __future__ import annotations

import argparse
import pathlib
import struct
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]

PARTITION = struct.Struct("<HBBII16sI")
VALID_MAGIC = 0x50AA
FLASH_BYTES = 16 * 1024 * 1024

def run() -> int:
    parser = argparse.ArgumentParser(description="Read-only InfoTAB partition audit")
    parser.add_argument("--env", choices=("infotab_tab5", "infotab_tab5_16mb_audit"),
                        default="infotab_tab5", help="PlatformIO build environment")
    args = parser.parse_args()
    build = ROOT / ".pio" / "build" / args.env
    table = build / "partitions.bin"
    firmware = build / "firmware.bin"
    print(f"[InfoTAB] Local read-only partition audit — {args.env}")
    if not table.is_file():
        print("ERROR: partitions.bin not found. Run the normal PlatformIO Build first.")
        return 2
    payload = table.read_bytes()
    slots = []
    parsed = []
    for off in range(0, len(payload) - PARTITION.size + 1, PARTITION.size):
        magic, typ, subtype, address, size, raw_label, flags = PARTITION.unpack_from(payload, off)
        if magic == 0xFFFF:
            break
        if magic == 0xEBEB:  # ESP-IDF partition checksum marker
            break
        if magic != VALID_MAGIC:
            print(f"ERROR: unexpected partition magic 0x{magic:04X} at table offset 0x{off:X}")
            return 3
        label = raw_label.split(b"\0", 1)[0].decode("ascii", errors="replace")
        parsed.append((label, typ, subtype, address, size))
        print(f"  {label:<16} type=0x{typ:02X} subtype=0x{subtype:02X} "
              f"offset=0x{address:06X} size={size // 1024} KiB")
        if address + size > FLASH_BYTES:
            print(f"ERROR: {label} extends past 16MB Flash")
            return 4
        if typ == 0x00 and subtype in (0x10, 0x11):  # ota_0, ota_1
            slots.append((label, subtype, address, size))
    if not parsed:
        print("ERROR: no partition entries found")
        return 5
    if firmware.is_file():
        binary_size = firmware.stat().st_size
        print(f"\n  firmware.bin: {binary_size} B ({binary_size / 1024:.1f} KiB)")
    else:
        binary_size = None
        print("\n  firmware.bin missing (not all builds produce it)")
    print("  OTA app slots:", len(slots))
    for label, subtype, address, size in slots:
        margin = "unknown" if binary_size is None else f"{size - binary_size} B"
        print(f"  {label}: {size // 1024} KiB, free after firmware: {margin}")
    if len(slots) != 2:
        print("\n  RESULT: BLOCKED — expected two OTA app slots.")
    elif min(p[3] for p in slots) <= 0x140000:
        print("\n  RESULT: SMALL OTA SLOTS — current table resembles 4MB default.csv.")
        print("  STOP: do not change partition layout or flash an OTA image yet.")
    else:
        print("\n  RESULT: OTA A/B slots present; runtime table and rollback still require checking.")
    print("  NOTE: this reads the LOCAL BUILD only, not the table already flashed on Tab5.")

    if args.env == "infotab_tab5_16mb_audit":
        entries = {p[0]: p for p in parsed}
        required = {
            "nvs": (0x9000, 0x5000),
            "otadata": (0xE000, 0x2000),
            "app0": (0x10000, 0x640000),
            "app1": (0x650000, 0x640000),
        }
        mismatch = []
        for label, (offset, size) in required.items():
            p = entries.get(label)
            if p is None or p[3] != offset or p[4] != size:
                mismatch.append(label)
        if binary_size is None or binary_size > 0x640000:
            mismatch.append("firmware.bin")
        if mismatch:
            print("  CANDIDATE FAIL: invalid 16MB layout: " + ", ".join(mismatch))
            print("  DO NOT UPLOAD.")
            return 6
        print("  CANDIDATE PASS: 16MB build has 2 x 6.25 MiB slots, NVS unchanged.")
        print("  DO NOT UPLOAD — USB migration and backup are still pending.")
    return 0

if __name__ == "__main__":
    sys.exit(run())
